import { mapState } from "vuex";
import { cmsListApi, categoryListApi, relationApi } from "@/api/cms";
import relationList from "./relation";
import { formatDate } from "@/utils/validate";
import goodsList from "@/components/goodsList/index";
export default {
  name: "addArticle",
  data() {
    return {
      modalTitleSs: "",
      currentTab: "",
      grid: {
        xl: 8,
        lg: 8,
        md: 12,
        sm: 24,
        xs: 24,
      },
      loading: false,
      artFrom: {
        pid: 0,
        title: "",
        page: 1,
        limit: 20,
      },
      total: 0,
      columns1: [
        {
          title: "ID",
          key: "id",
          width: 80,
        },
        {
          title: "文章图片",
          slot: "image_inputs",
          minWidth: 90,
        },
        {
          title: "文章名称",
          slot: "titles",
          minWidth: 130,
        },
        {
          title: "关联商品",
          key: "store_name",
          minWidth: 130,
        },
        // {
        //     title: '排序',
        //     key: 'sort',
        //     minWidth: 60
        // },
        {
          title: "浏览量",
          key: "visit",
          minWidth: 80,
        },
        {
          title: "时间",
          key: "add_time",
          sortable: true,
          render: (h, params) => {
            return h(
              "div",
              formatDate(
                new Date(Number(params.row.add_time) * 1000),
                "yyyy-MM-dd hh:mm"
              )
            );
          },
          minWidth: 120,
        },
        {
          title: "操作",
          slot: "action",
          fixed: "right",
          minWidth: 170,
        },
      ],
      cmsList: [],
      treeData: [],
      cid: 0, // 移动分类id
      cmsId: 0,
      formValidate: {
        type: 1,
      },
      rows: {},
      modal_loading: false,
      modals: false,
    };
  },
  components: {
    relationList,
    goodsList,
  },
  computed: {
    ...mapState("admin/layout", ["isMobile"]),
    labelWidth() {
      return this.isMobile ? undefined : 96;
    },
    labelPosition() {
      return this.isMobile ? "top" : "right";
    },
  },
  mounted() {
    this.artFrom.pid = this.$route.query.id ? this.$route.query.id : 0;
    this.getList();
    this.getClass();
  },
  methods: {
    // 关联成功
    getProductId(row) {
      let data = {
        product_id: row.id,
      };
      relationApi(data, this.rows.id)
        .then(async (res) => {
          this.$Message.success(res.msg);
          row.id = 0;
          this.modal_loading = false;
          this.modals = false;
          setTimeout(() => {
            this.getList();
          }, 500);
        })
        .catch((res) => {
          this.modal_loading = false;
          this.loading = false;
          this.$Message.error(res.msg);
        });
    },
    cancel() {
      this.modals = false;
    },
    // 等级列表
    getList() {
      this.loading = true;
      cmsListApi(this.artFrom)
        .then(async (res) => {
          let data = res.data;
          this.cmsList = data.list;
          this.total = data.count;
          this.loading = false;
        })
        .catch((res) => {
          this.loading = false;
          this.$Message.error(res.msg);
        });
    },
    // 分类
    getClass() {
      categoryListApi(this.formValidate)
        .then(async (res) => {
          let data = res.data;
          this.treeData = data;
          // let obj = {
          //     id: 0,
          //     title: '全部'
          // }
          // this.treeData.unshift(obj);
        })
        .catch((res) => {
          this.$Message.error(res.msg);
        });
    },
    pageChange(index) {
      this.artFrom.page = index;
      this.getList();
    },
    // 编辑
    edit(row) {
      this.$router.push({
        path: "/admin/content/article/add_article/" + row.id,
      });
    },
    // 关联
    artRelation(row, tit, num) {
      this.rows = row;
      if (row.product_id === 0) {
        this.modals = true;
      } else {
        let delfromData = {
          title: tit,
          num: num,
          url: `/cms/cms/unrelation/${row.id}`,
          method: "PUT",
          ids: "",
        };
        this.$modalSure(delfromData)
          .then((res) => {
            this.$Message.success(res.msg);
            this.getList();
          })
          .catch((res) => {
            this.$Message.error(res.msg);
          });
      }
    },
    // 删除
    del(row, tit, num) {
      let delfromData = {
        title: tit,
        num: num,
        url: `cms/cms/${row.id}`,
        method: "DELETE",
        ids: "",
      };
      this.$modalSure(delfromData)
        .then((res) => {
          this.$Message.success(res.msg);
          this.cmsList.splice(num, 1);
          if (!this.cmsList.length) {
            this.artFrom.page =
              this.artFrom.page == 1 ? 1 : this.artFrom.page - 1;
          }
          this.getList();
        })
        .catch((res) => {
          this.$Message.error(res.msg);
        });
    },
    // 表格搜索
    userSearchs() {
      this.artFrom.page = 1;
      this.getList();
    },
  },
};
